import{_ as i,o as n,c as t,ae as o}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"🧱 SOLID Principles - TenderCheck AI Engineering Standards","description":"","frontmatter":{},"headers":[],"relativePath":"standards/solid_principles.md","filePath":"standards/solid_principles.md"}'),l={name:"standards/solid_principles.md"};function r(s,e,a,c,d,p){return n(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="🧱-solid-principles-tendercheck-ai-engineering-standards" tabindex="-1">🧱 SOLID Principles - TenderCheck AI Engineering Standards <a class="header-anchor" href="#🧱-solid-principles-tendercheck-ai-engineering-standards" aria-label="Permalink to &quot;🧱 SOLID Principles - TenderCheck AI Engineering Standards&quot;">​</a></h1><h2 id="_1-single-responsibility-principle-srp" tabindex="-1">1. Single Responsibility Principle (SRP) <a class="header-anchor" href="#_1-single-responsibility-principle-srp" aria-label="Permalink to &quot;1. Single Responsibility Principle (SRP)&quot;">​</a></h2><ul><li>[cite_start]<strong>Definition</strong>: A class or module should have one, and only one, reason to change[cite: 526].</li><li><strong>Project Application</strong>: <ul><li>The <code>PdfParserService</code> only extracts text; it does not validate requirements.</li><li>The <code>ValidationResult</code> entity only holds data; it doesn&#39;t contain the logic to generate a PDF report.</li></ul></li></ul><h2 id="_2-open-closed-principle-ocp" tabindex="-1">2. Open/Closed Principle (OCP) <a class="header-anchor" href="#_2-open-closed-principle-ocp" aria-label="Permalink to &quot;2. Open/Closed Principle (OCP)&quot;">​</a></h2><ul><li><strong>Definition</strong>: Software entities should be open for extension, but closed for modification.</li><li><strong>Project Application</strong>: <ul><li>The <code>ValidationEngine</code> should be able to accept new <code>ValidationRules</code> without changing its core execution loop.</li><li>If we add a new AI provider (e.g., Anthropic), we extend the infrastructure without modifying the application use cases.</li></ul></li></ul><h2 id="_3-liskov-substitution-principle-lsp" tabindex="-1">3. Liskov Substitution Principle (LSP) <a class="header-anchor" href="#_3-liskov-substitution-principle-lsp" aria-label="Permalink to &quot;3. Liskov Substitution Principle (LSP)&quot;">​</a></h2><ul><li><strong>Definition</strong>: Objects of a superclass should be replaceable with objects of its subclasses without breaking the system.</li><li><strong>Project Application</strong>: <ul><li>Any implementation of the <code>DocumentProcessor</code> interface (Local PDF, Cloud OCR) must return the same normalized text format so the system remains stable.</li></ul></li></ul><h2 id="_4-interface-segregation-principle-isp" tabindex="-1">4. Interface Segregation Principle (ISP) <a class="header-anchor" href="#_4-interface-segregation-principle-isp" aria-label="Permalink to &quot;4. Interface Segregation Principle (ISP)&quot;">​</a></h2><ul><li><strong>Definition</strong>: No client should be forced to depend on methods it does not use.</li><li><strong>Project Application</strong>: <ul><li>Instead of one giant <code>AIService</code>, we use specific interfaces like <code>RequirementExtractor</code> and <code>ComplianceValidator</code>. [cite_start]This keeps the &quot;Reasoning Layer&quot; lean and focused[cite: 1036].</li></ul></li></ul><h2 id="_5-dependency-inversion-principle-dip" tabindex="-1">5. Dependency Inversion Principle (DIP) <a class="header-anchor" href="#_5-dependency-inversion-principle-dip" aria-label="Permalink to &quot;5. Dependency Inversion Principle (DIP)&quot;">​</a></h2><ul><li><strong>Definition</strong>: High-level modules should not depend on low-level modules. Both should depend on abstractions.</li><li><strong>Project Application</strong>: <ul><li>The <code>AnalyzeTenderUseCase</code> (High-level) depends on the <code>IDocumentRepository</code> interface, not on a specific database or file system (Low-level). [cite_start]This is the core of our <strong>Hexagonal Architecture</strong>[cite: 535, 1010].</li></ul></li></ul>',11)])])}const g=i(l,[["render",r]]);export{h as __pageData,g as default};
